	CHECK (rule_revision>0 AND rule_sha256 ~ '^[0-9a-f]{64}$' AND issuer_epoch>0 AND executor_id=writer_id AND observed_until>observed_from AND length(issuer_key) BETWEEN 1 AND 100 AND length(issuer_version) BETWEEN 1 AND 100), 
	CHECK (COALESCE((fact_body->'body')->'rule'->>'id'=rule_fact_id::text AND ((fact_body->'body')->'rule'->>'revision')::integer=rule_revision AND (fact_body->'body')->'rule'->>'sha256'=rule_sha256 AND (fact_body->'body')->'issuer'->>'key'=issuer_key AND (fact_body->'body')->'issuer'->>'version'=issuer_version AND ((fact_body->'body')->'issuer'->>'epoch')::integer=issuer_epoch AND (fact_body->'body')->'issuer'->>'nature'=nature AND (fact_body->'body')->>'executor_id'=executor_id::text AND ((fact_body->'body')->>'observed_from')::timestamptz=observed_from AND ((fact_body->'body')->>'observed_until')::timestamptz=observed_until,false))
)

;

CREATE INDEX ix_capa_observation_facts_tenant_id ON capa_observation_facts (tenant_id);


CREATE TABLE capa_current_observations (
	series_id UUID NOT NULL, 
	fact_id UUID NOT NULL, 
	fact_revision INTEGER NOT NULL, 
	epoch INTEGER NOT NULL, 
	product_id UUID NOT NULL, 
	project_id UUID NOT NULL, 
	issue_id UUID NOT NULL, 
	capa_id UUID NOT NULL, 
	origin_issue_version_id UUID NOT NULL, 
	origin_issue_revision INTEGER NOT NULL, 
	owner_id UUID NOT NULL, 
	visibility VARCHAR(16) NOT NULL, 
	nature VARCHAR(16) NOT NULL, 
	purpose TEXT NOT NULL, 
	anchor_snapshot JSONB NOT NULL, 
	anchor_sha256 VARCHAR(64) NOT NULL, 
	requirement_sha256 VARCHAR(64) NOT NULL, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, product_id, project_id, issue_id, origin_issue_version_id, origin_issue_revision) REFERENCES quality_issue_versions (tenant_id, product_id, project_id, issue_id, id, revision) DEFERRABLE INITIALLY DEFERRED, 
	CHECK (origin_issue_revision>0 AND visibility IN ('private','product') AND nature IN ('real','synthetic') AND length(purpose) BETWEEN 1 AND 2000 AND purpose=btrim(purpose)), 
	CHECK (anchor_sha256 ~ '^[0-9a-f]{64}$' AND requirement_sha256 ~ '^[0-9a-f]{64}$'), 
	CHECK (COALESCE(jsonb_typeof(anchor_snapshot)='object' AND anchor_snapshot->>'anchor_sha256'=anchor_sha256 AND anchor_snapshot->'origin'->'ref'->>'id'=origin_issue_version_id::text AND (anchor_snapshot->'origin'->'ref'->>'revision')::integer=origin_issue_revision AND anchor_snapshot->'origin'->>'issue_id'=issue_id::text AND anchor_snapshot->'origin'->'issue'->'capa'->>'id'=capa_id::text AND anchor_snapshot->'origin'->'scope'->>'tenant_id'=tenant_id::text AND anchor_snapshot->'origin'->'scope'->>'product_id'=product_id::text AND anchor_snapshot->'origin'->'scope'->>'project_id'=project_id::text AND anchor_snapshot->'origin'->>'owner_id'=owner_id::text AND anchor_snapshot->'origin'->>'visibility'=visibility AND anchor_snapshot->'origin'->>'nature'=nature AND anchor_snapshot->'origin'->>'purpose'=purpose,false)), 
	UNIQUE (tenant_id, product_id, project_id, issue_id, capa_id, series_id), 
	FOREIGN KEY(tenant_id, product_id, project_id, issue_id, capa_id, origin_issue_version_id, origin_issue_revision, owner_id, visibility, nature, anchor_sha256, requirement_sha256, series_id, fact_id, fact_revision) REFERENCES capa_observation_facts (tenant_id, product_id, project_id, issue_id, capa_id, origin_issue_version_id, origin_issue_revision, owner_id, visibility, nature, anchor_sha256, requirement_sha256, series_id, id, revision) DEFERRABLE INITIALLY DEFERRED, 
	CHECK (fact_revision>0 AND epoch>0)
)

;

CREATE INDEX ix_capa_current_observations_tenant_id ON capa_current_observations (tenant_id);


CREATE TABLE capa_named_verification_reviews (
	candidate_id UUID NOT NULL, 
	candidate_revision INTEGER NOT NULL, 
	candidate_sha256 VARCHAR(64) NOT NULL, 
	rule_fact_id UUID NOT NULL, 
	rule_revision INTEGER NOT NULL, 
	rule_sha256 VARCHAR(64) NOT NULL, 
	reviewer_id UUID NOT NULL, 
	valid_until TIMESTAMP WITH TIME ZONE NOT NULL, 
	revision INTEGER NOT NULL, 
	writer_id UUID NOT NULL, 
	actor_id UUID NOT NULL, 
	requester_id UUID NOT NULL, 
	command_id UUID NOT NULL, 
	operation VARCHAR(80) NOT NULL, 
	tier VARCHAR(16) NOT NULL, 
	fact_kind VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	fact_body JSONB NOT NULL, 
	payload_sha256 VARCHAR(64) NOT NULL, 
	intent_digest VARCHAR(64) NOT NULL, 
	sources JSONB NOT NULL, 
	required_source_read_set JSONB NOT NULL, 
	source_basis JSONB NOT NULL, 
	read_set_sha256 VARCHAR(64) NOT NULL, 
	input_snapshot JSONB NOT NULL, 
	authority_snapshot JSONB NOT NULL, 
	policy_snapshot JSONB NOT NULL, 
	shared_proof_id UUID, 
	shared_proof_revision INTEGER, 
	proof_expires_at TIMESTAMP WITH TIME ZONE, 
	proof_consumed_at TIMESTAMP WITH TIME ZONE, 
	token_sha256 VARCHAR(64), 
	material_sha256 VARCHAR(64), 
	product_id UUID NOT NULL, 
	project_id UUID NOT NULL, 
	issue_id UUID NOT NULL, 
	capa_id UUID NOT NULL, 
	origin_issue_version_id UUID NOT NULL, 
	origin_issue_revision INTEGER NOT NULL, 
	owner_id UUID NOT NULL, 
	visibility VARCHAR(16) NOT NULL, 
	nature VARCHAR(16) NOT NULL, 
	purpose TEXT NOT NULL, 
	anchor_snapshot JSONB NOT NULL, 
	anchor_sha256 VARCHAR(64) NOT NULL, 
	requirement_sha256 VARCHAR(64) NOT NULL, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, product_id, project_id, issue_id, origin_issue_version_id, origin_issue_revision) REFERENCES quality_issue_versions (tenant_id, product_id, project_id, issue_id, id, revision) DEFERRABLE INITIALLY DEFERRED, 
	CHECK (origin_issue_revision>0 AND visibility IN ('private','product') AND nature IN ('real','synthetic') AND length(purpose) BETWEEN 1 AND 2000 AND purpose=btrim(purpose)), 
	CHECK (anchor_sha256 ~ '^[0-9a-f]{64}$' AND requirement_sha256 ~ '^[0-9a-f]{64}$'), 
	CHECK (COALESCE(jsonb_typeof(anchor_snapshot)='object' AND anchor_snapshot->>'anchor_sha256'=anchor_sha256 AND anchor_snapshot->'origin'->'ref'->>'id'=origin_issue_version_id::text AND (anchor_snapshot->'origin'->'ref'->>'revision')::integer=origin_issue_revision AND anchor_snapshot->'origin'->>'issue_id'=issue_id::text AND anchor_snapshot->'origin'->'issue'->'capa'->>'id'=capa_id::text AND anchor_snapshot->'origin'->'scope'->>'tenant_id'=tenant_id::text AND anchor_snapshot->'origin'->'scope'->>'product_id'=product_id::text AND anchor_snapshot->'origin'->'scope'->>'project_id'=project_id::text AND anchor_snapshot->'origin'->>'owner_id'=owner_id::text AND anchor_snapshot->'origin'->>'visibility'=visibility AND anchor_snapshot->'origin'->>'nature'=nature AND anchor_snapshot->'origin'->>'purpose'=purpose,false)), 
	UNIQUE (tenant_id, product_id, id), 
	UNIQUE (tenant_id, product_id, project_id, issue_id, capa_id, id, revision), 
	UNIQUE (tenant_id, product_id, writer_id, intent_digest), 
	UNIQUE (tenant_id, shared_proof_id), 
	FOREIGN KEY(tenant_id, writer_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, requester_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, shared_proof_id) REFERENCES confirmations (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	CHECK (revision>0 AND operation='quality.capa.verification.review' AND tier='T2' AND fact_kind='review' AND status='reviewed' AND actor_id=requester_id AND writer_id=actor_id), 
	CHECK (shared_proof_id IS NOT NULL AND shared_proof_revision IS NOT NULL AND shared_proof_revision>0 AND proof_expires_at IS NOT NULL AND proof_consumed_at IS NOT NULL AND proof_consumed_at<=created_at AND created_at<proof_expires_at AND token_sha256 IS NOT NULL AND material_sha256 IS NOT NULL AND token_sha256 ~ '^[0-9a-f]{64}$' AND material_sha256 ~ '^[0-9a-f]{64}$'), 
	CHECK (payload_sha256 ~ '^[0-9a-f]{64}$' AND intent_digest ~ '^[0-9a-f]{64}$' AND read_set_sha256 ~ '^[0-9a-f]{64}$'), 
	CHECK (COALESCE(jsonb_typeof(fact_body)='object' AND fact_body->>'schema_version'='pdos-capa-fact-body-v1' AND (fact_body - ARRAY['schema_version','body'])='{}'::jsonb AND jsonb_typeof((fact_body->'body'))='object' AND (fact_body->'body') ?& ARRAY['ref','previous','scope','issue_id','capa_id','purpose','anchor_sha256','requirement_sha256','nature','owner_id','visibility','created_at','sources','required_source_read_set','source_basis','kind','candidate','candidate_sha256','rule','observations','reviewer_id','at','pair_applicability','action_fulfillment','participants','participant_owner_material','conclusion','reason','authority_snapshot','policy_snapshot','valid_until'] AND ((fact_body->'body') - ARRAY['ref','previous','scope','issue_id','capa_id','purpose','anchor_sha256','requirement_sha256','nature','owner_id','visibility','created_at','sources','required_source_read_set','source_basis','kind','candidate','candidate_sha256','rule','observations','reviewer_id','at','pair_applicability','action_fulfillment','participants','participant_owner_material','conclusion','reason','authority_snapshot','policy_snapshot','valid_until'])='{}'::jsonb AND (fact_body->'body')->>'kind'=fact_kind AND (fact_body->'body')->'ref'->>'id'=id::text AND ((fact_body->'body')->'ref'->>'revision')::integer=revision AND (((fact_body->'body')->'ref') - ARRAY['id','revision'])='{}'::jsonb AND (fact_body->'body')->'scope'->>'tenant_id'=tenant_id::text AND (fact_body->'body')->'scope'->>'product_id'=product_id::text AND (fact_body->'body')->'scope'->>'project_id'=project_id::text AND (fact_body->'body')->>'issue_id'=issue_id::text AND (fact_body->'body')->>'capa_id'=capa_id::text AND (fact_body->'body')->>'owner_id'=owner_id::text AND (fact_body->'body')->>'visibility'=visibility AND (fact_body->'body')->>'nature'=nature AND (fact_body->'body')->>'purpose'=purpose AND (fact_body->'body')->>'anchor_sha256'=anchor_sha256 AND (fact_body->'body')->>'requirement_sha256'=requirement_sha256 AND ((fact_body->'body')->>'created_at')::timestamptz=created_at,false)), 
	CHECK (COALESCE(jsonb_typeof(required_source_read_set)='array' AND jsonb_array_length(required_source_read_set) BETWEEN 1 AND 20 AND jsonb_typeof(source_basis)='array' AND jsonb_array_length(source_basis) BETWEEN 1 AND 20 AND jsonb_typeof(sources)='array' AND jsonb_array_length(sources)>0 AND required_source_read_set=(fact_body->'body')->'required_source_read_set' AND source_basis=(fact_body->'body')->'source_basis' AND sources=(fact_body->'body')->'sources',false)), 
	CHECK (COALESCE(jsonb_typeof(input_snapshot)='object' AND jsonb_typeof(authority_snapshot)='object' AND jsonb_typeof(policy_snapshot)='object',false) AND NOT (input_snapshot ? 'confirmation_token') AND NOT (input_snapshot ? 'approval_token')), 
	FOREIGN KEY(tenant_id, product_id, project_id, issue_id, capa_id, candidate_id) REFERENCES capa_verification_evidence (tenant_id, product_id, project_id, issue_id, capa_id, id) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, product_id, project_id, issue_id, capa_id, rule_fact_id, rule_revision) REFERENCES capa_verification_rule_facts (tenant_id, product_id, project_id, issue_id, capa_id, id, revision) DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(tenant_id, reviewer_id) REFERENCES principals (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, 
	CHECK (revision=1 AND candidate_revision=1 AND rule_revision>0 AND reviewer_id=writer_id AND valid_until>created_at AND candidate_sha256 ~ '^[0-9a-f]{64}$' AND rule_sha256 ~ '^[0-9a-f]{64}$'), 
	CHECK (COALESCE((fact_body->'body')->'previous'='null'::jsonb AND (fact_body->'body')->'candidate'->>'id'=candidate_id::text AND ((fact_body->'body')->'candidate'->>'revision')::integer=candidate_revision AND (fact_body->'body')->'candidate'->>'sha256'=candidate_sha256 AND (fact_body->'body')->>'candidate_sha256'=candidate_sha256 AND (fact_body->'body')->'rule'->>'id'=rule_fact_id::text AND ((fact_body->'body')->'rule'->>'revision')::integer=rule_revision AND (fact_body->'body')->'rule'->>'sha256'=rule_sha256 AND (fact_body->'body')->>'reviewer_id'=reviewer_id::text AND (fact_body->'body')->'authority_snapshot'=authority_snapshot AND (fact_body->'body')->'policy_snapshot'=policy_snapshot AND ((fact_body->'body')->>'valid_until')::timestamptz=valid_until,false))
)

;

